      tableNotes: [
        [
          'Russet Mold: Identification. This reddish-brown mold grows in darkness and damp warmth. On metal, a successful DC 15 Intelligence (Nature) or Wisdom (Survival) check distinguishes it from rust.\nExposure. A creature that comes within 5 ft. must make a DC 13 Constitution save against the released spores. On a failure, it is poisoned and takes 7 (2d6) poison damage at the start of each of its turns as mold sprouts on it. At the end of each of its turns, it can repeat the save to end the effect. Magic that neutralizes poison or cures disease also destroys the infestation.\nNew growth. A creature dies if this damage reduces it to 0 HP. If the victim is a beast, giant, or humanoid, its corpse produces newborn Vegepygmies after 24 hours. A Small corpse produces one, Medium two, Large four, Huge eight, and Gargantuan sixteen. Moldies born from beasts take the form of Thornies.\nClearing it. Each point of acid, necrotic, or radiant damage clears 1 square foot. A pound of salt, a gallon of alcohol, or magic that cures disease clears a 10-foot square. Sunlight destroys exposed patches. Weapons and most other damage have no effect.',
        ],
      ],
